from lib import *
chapter(7,'maths','working-with-fractions','Working with Fractions',
 ('Sharing a cake','Half a cake is shared among 3 children. How much does each get? That is half divided by 3. This chapter shows how to multiply and divide fractions.'),
 [('Adding and subtracting',['To add or subtract fractions with different denominators, first write them with a common denominator.','Then add or subtract the numerators and keep the denominator. One half plus one third is three sixths plus two sixths, which is five sixths.']),
  ('Multiplying fractions',['To multiply fractions, multiply the numerators together and the denominators together.','Two thirds of three fourths is 2 times 3 over 3 times 4, which is 6 over 12, or one half.','Multiplying a fraction by a whole number repeats the fraction: 3 times 1 over 4 is 3 over 4.','Multiplying by a fraction less than 1 gives a smaller number.']),
  ('Dividing fractions',['The reciprocal of a fraction is found by swapping numerator and denominator. The reciprocal of 3 over 4 is 4 over 3.','To divide by a fraction, multiply by its reciprocal. Half divided by 3 is half times one third, which is one sixth.']),
  ('Problems',['Read the problem, decide whether it asks you to share, take a part of a part or repeat, then choose the operation.'])],
 [('Find 2/3 of 3/4.',[('Multiply numerators: 2 times 3 is 6.','Numerators.'),('Multiply denominators: 3 times 4 is 12; 6/12 is 1/2.','Simplify.')]),
  ('Find 1/2 divided by 3.',[('Reciprocal of 3 is 1/3.','Flip.'),('1/2 times 1/3 is 1/6.','Multiply.')])],
 ('Explain why dividing by 2 is the same as multiplying by one half.',['Half of something is the same as dividing by 2.','The reciprocal of 2 is 1/2.'],['Adding denominators.','Forgetting to flip when dividing.']),
 ['Common denominator to add or subtract.','Multiply numerators and denominators to multiply.','Divide by multiplying with the reciprocal.'],
 [num('1',1,'1/2 + 1/3: the numerator over 6 is',5,'3/6 plus 2/6.',[(2,'Add 3 and 2, not 1 and 1.')]),
  mcq('2',1,'2/3 x 3/4 =','1/2',[('5/7','Do not add numerators and denominators.'),('6/7','Multiply denominators too.')],'6/12 simplifies to 1/2.'),
  mcq('3',1,'The reciprocal of 3/4 is','4/3',[('3/4','That is the same fraction.'),('-3/4','That is the negative.')],'Flip it.'),
  tf('4',1,'Multiplying by 1/2 makes a number smaller.',True,'Half of it is less.'),
  mcq('5',2,'1/2 divided by 3 is','1/6',[('3/2','That is 3 divided by 1/2... flipped incorrectly.'),('6','That is 3 times 2.')],'1/2 times 1/3.'),
  mcq('6',2,'3/5 divided by 3/10 =','2',[('1/2','Check: 3/5 times 10/3 is 2.'),('9/50','That multiplies without flipping.')],'3/5 times 10/3 is 30/15.'),
  num('7',2,'3 x 1/4 = ?/4',3,'Three quarters.',[(12,'Do not multiply the denominator.')]),
  mcq('8',3,'1 3/4 + 2 1/4 =','4',[('3 4/8','Add numerators over the same denominator.'),('3 1/2','Check the sum of the fractions.')],'1+2 is 3 and 3/4+1/4 is 1.')],
 keep=['reciprocal','numerator','denominator'])
chapter(7,'maths','geometric-twins','Geometric Twins',
 ('Two bangles','Two bangles of the same size fit exactly one over the other. Shapes that are exactly alike in size and shape are called congruent. They are geometric twins.'),
 [('Congruent shapes',['Two shapes are congruent if one can be placed exactly on the other by sliding, turning or flipping.','Congruent shapes have equal sides and equal angles in matching positions.','Shapes that look alike but differ in size are not congruent.']),
  ('Testing congruence of triangles',['Two triangles are congruent if three pairs of matching sides and three pairs of matching angles are equal.','But we do not need all six facts. Certain smaller sets are enough.']),
  ('Conditions for congruence',['SSS: three sides equal to three sides.','SAS: two sides and the angle between them equal.','ASA: two angles and the side between them equal.','RHS: in right triangles, hypotenuse and one side equal.','Two sides and an angle not between them is not enough.'])],
 [('Triangles ABC and PQR have AB=PQ, BC=QR and CA=RP. Are they congruent?',[('All three pairs of sides are equal.','Check sides.'),('By SSS they are congruent.','Conclusion.')])],
 ('Explain why two squares of equal side are congruent but two rectangles may not be.',['Squares have all sides equal.','Rectangles can have different length-breadth pairs.'],['Thinking equal angles alone make shapes congruent.']),
 ['Congruent means same shape and size.','SSS, SAS, ASA and RHS test triangles.','Matching parts are equal.'],
 [mcq('1',1,'Congruent shapes have','the same shape and size',[('the same shape only','Similar shapes are same in shape only.'),('the same colour','Colour does not matter.')],'They fit exactly.'),
  mcq('2',1,'SSS means','all three sides equal',[('two sides and one angle','This is SAS or SSA.'),('three angles equal','Angles alone are not enough.')],'Three sides to three sides.'),
  tf('3',1,'Two circles of the same radius are congruent.',True,'They fit exactly.'),
  mcq('4',1,'Which is enough for congruence?','Two sides and the included angle',[('Three angles','The triangles may differ in size.'),('One side','One side is not enough.')],'SAS.'),
  mcq('5',2,'RHS is used for','right-angled triangles',[('any triangles','It needs a right angle.'),('circles','Not for circles.')],'Hypotenuse and a side.'),
  tf('6',2,'Two triangles with equal angles must be congruent.',False,'They may be different sizes.'),
  mcq('7',2,'Two rectangles are congruent if','both length and breadth match',[('only length matches','The breadth may differ.'),('perimeters are equal','Different rectangles can have equal perimeters.')],'All sides must match.'),
  num('8',3,'Congruent triangles: side 5 cm matches side PQ. PQ =',5,'Matching parts are equal.',[(10,'Congruent means equal, not double.')],'cm')],
 keep=['congruent','SSS','SAS'])
chapter(7,'maths','operations-with-integers','Operations with Integers',
 ('Scores in a game','In a quiz, a correct answer gives plus 4 and a wrong answer gives minus 1. If you get 3 right and 2 wrong, what is your score? We need clear rules for adding and multiplying integers.'),
 [('Adding and subtracting',['To add a positive integer move right on the number line. To add a negative integer move left.','To subtract an integer, add its opposite. 5 minus (-3) equals 5 plus 3, which is 8.']),
  ('Multiplying integers',['A positive times a positive is positive. A positive times a negative is negative. A negative times a negative is positive.','So 3 times -2 is -6 and -3 times -2 is 6.','Think of -3 times -2 as taking away three groups of minus 2, which gives 6.']),
  ('Dividing integers',['The rules for signs are the same. A negative divided by a negative is positive. A negative divided by a positive is negative.']),
  ('Brahmagupta\'s rules',['The Indian mathematician Brahmagupta described rules for dealing with negative numbers more than 1,400 years ago, treating them as debts.'])],
 [('Find 3 x (-4) + 5.',[('3 times -4 is -12.','Positive times negative.'),('-12 plus 5 is -7.','Move right 5.')])],
 ('Explain why a negative times a negative is positive.',['Use a pattern: -2 times 3, 2, 1, 0 gives -6, -4, -2, 0.','The next must be 2, 4, 6.'],['Writing the same sign when signs differ.']),
 ['Subtract = add the opposite.','Same signs multiply to positive; different signs to negative.','Division follows the same rules.'],
 [num('1',1,'5 - (-3) = ?',8,'Subtracting -3 is adding 3.',[(2,'You treated it as 5 minus 3.')]),
  num('2',1,'3 x (-4) = ?',-12,'Positive times negative is negative.',[(12,'The signs differ so the answer is negative.')]),
  num('3',1,'(-3) x (-2) = ?',6,'Negative times negative is positive.',[(-6,'Signs are the same so positive.')]),
  tf('4',1,'A negative divided by a positive is negative.',True,'Different signs give negative.'),
  num('5',2,'(-12) / (-3) = ?',4,'Same signs give positive.',[(-4,'Both are negative so answer is positive.')]),
  num('6',2,'3 x (-4) + 5 = ?',-7,'-12 plus 5.',[(17,'Remember the sign of the product.')]),
  mcq('7',2,'-8 + 3 equals','-5',[('5','Start at -8 and move right 3.'),('-11','That adds the wrong way.')],'Number line.'),
  num('8',3,'Quiz: 3 right at +4 and 2 wrong at -1. Score is',10,'12 minus 2.',[(14,'You forgot the negative marks.')])],
 keep=['integer','opposite'])
chapter(7,'maths','finding-common-ground','Finding Common Ground',
 ('Two bells','Two bells ring: one every 12 minutes and one every 18 minutes. When will they ring together again? We find common multiples and common factors to answer such questions.'),
 [('HCF',['A factor divides a number exactly. The common factors of 12 and 18 are 1, 2, 3 and 6.','The highest common factor, HCF, is the greatest of them: 6.','HCF is useful for cutting things into the biggest equal pieces.']),
  ('LCM',['A multiple of a number is obtained by multiplying it with 1, 2, 3 and so on.','The least common multiple, LCM, of 12 and 18 is 36, the smallest number that both divide into.','LCM tells when events repeat together.']),
  ('Using prime factorisation',['Write each number as a product of primes. 12 is 2 times 2 times 3 and 18 is 2 times 3 times 3.','The HCF takes the common primes: 2 times 3 is 6. The LCM takes the highest power of every prime: 2 times 2 times 3 times 3 is 36.','HCF times LCM of two numbers equals the product of the numbers.'])],
 [('Two bells ring every 12 and 18 minutes. When do they ring together again?',[('Find the LCM of 12 and 18.','The first common multiple.'),('LCM is 36, so after 36 minutes.','Answer.')])],
 ('Explain when you use HCF and when you use LCM.',['HCF for the largest equal groups or pieces.','LCM for when events happen together again.'],['Mixing up HCF and LCM.']),
 ['HCF is the greatest common factor.','LCM is the smallest common multiple.','HCF x LCM = product of the two numbers.'],
 [num('1',1,'HCF of 12 and 18',6,'Common factors are 1, 2, 3 and 6.',[(36,'That is the LCM.')]),
  num('2',1,'LCM of 4 and 6',12,'Multiples of 4: 4, 8, 12. Multiples of 6: 6, 12.',[(24,'It is common but not least.')]),
  tf('3',1,'The HCF of two numbers can be larger than either number.',False,'It divides both so it cannot be larger than the smaller.'),
  mcq('4',1,'Which question needs LCM?','When will two buses meet again?',[('Cutting ribbons into longest equal pieces','This is HCF.'),('Counting pencils','Not LCM.')],'Events repeating together.'),
  num('5',2,'HCF of 24 and 36',12,'24 = 2x2x2x3 and 36 = 2x2x3x3, common 2x2x3.',[(6,'Include both 2s and the 3.')]),
  num('6',2,'LCM of 8 and 12',24,'8 = 2x2x2 and 12 = 2x2x3, take 2x2x2x3.',[(96,'That is the product, not the LCM.')]),
  mcq('7',2,'HCF x LCM of 4 and 6 equals','24',[('12','That is the LCM.'),('10','That adds them.')],'2 times 12 is 24, and 4 times 6 is 24.'),
  num('8',3,'Longest tape to cut 36 m and 48 m ribbons into equal pieces (m)',12,'HCF of 36 and 48.',[(144,'That is their LCM.')],'m')],
 keep=['HCF','LCM','prime factorisation'])
